-- Rollback de 20261106_tercer_entrenador.sql
-- 1. Quitar la función nueva (antes, pasar a 'apoyo' o borrar los terceros si los hay).
delete from public.grupo_entrenadores_extra_app where rol = 'tercero';
drop function if exists public.guardar_tercer_entrenador_grupo_app(uuid, uuid);
-- 2. guardar_apoyo_reportes_grupo_app: volver a la versión anterior (borraba
--    todos los extra al cambiar el segundo y solo aceptaba principal/segundo
--    en el reparto manual):
CREATE OR REPLACE FUNCTION public.guardar_apoyo_reportes_grupo_app(p_grupo_id uuid, p_entrenador_apoyo_id uuid, p_responsables jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ declare v_item jsonb; v_alumno_id uuid; v_entrenador_id uuid; v_sesion_id uuid; v_principal uuid; v_apoyo_anterior uuid; begin if not public.es_coordinacion_operativa_app() then raise exception 'Solo coordinación puede repartir apoyos y responsables de reportes.'; end if; if p_grupo_id is null then return; end if; select g.sesion_id,ae.entrenador_id into v_sesion_id,v_principal from public.grupos g left join public.asignaciones_entrenadores ae on ae.grupo_id=g.id where g.id=p_grupo_id order by ae.created_at nulls last,ae.id limit 1; if v_sesion_id is null then raise exception 'No existe el grupo indicado.'; end if; select ge.entrenador_id into v_apoyo_anterior from public.grupo_entrenadores_extra_app ge where ge.grupo_id=p_grupo_id order by ge.created_at nulls last,ge.id limit 1; if p_entrenador_apoyo_id is not null then if p_entrenador_apoyo_id=v_principal then raise exception 'El segundo entrenador no puede ser el mismo que el principal.'; end if; if not public.entrenador_disponible_sesion_operativa_app(v_sesion_id,p_entrenador_apoyo_id) then raise exception 'El segundo entrenador no figura como Disponible para este turno.'; end if; if public.entrenador_ocupado_sesion_operativa_app(v_sesion_id,p_entrenador_apoyo_id,p_grupo_id) then raise exception 'Ese entrenador ya está asignado a un grupo que se solapa en ese turno.'; end if; end if; delete from public.grupo_entrenadores_extra_app where grupo_id=p_grupo_id; if p_entrenador_apoyo_id is not null then insert into public.grupo_entrenadores_extra_app(grupo_id,entrenador_id,rol) values(p_grupo_id,p_entrenador_apoyo_id,'apoyo') on conflict(grupo_id,entrenador_id) do update set rol=excluded.rol; end if; if p_responsables is null then if v_apoyo_anterior is not null then update public.grupo_reporte_responsable_app set entrenador_id=coalesce(p_entrenador_apoyo_id,v_principal) where grupo_id=p_grupo_id and entrenador_id=v_apoyo_anterior; elsif p_entrenador_apoyo_id is not null then insert into public.grupo_reporte_responsable_app(grupo_id,alumno_id,entrenador_id) select p_grupo_id, ga.alumno_id, case when (row_number() over (order by ga.alumno_id)) % 5 < 3 then v_principal else p_entrenador_apoyo_id end from public.grupo_alumnos ga where ga.grupo_id=p_grupo_id on conflict(grupo_id,alumno_id) do update set entrenador_id=excluded.entrenador_id; end if; return; end if; delete from public.grupo_reporte_responsable_app where grupo_id=p_grupo_id; for v_item in select * from jsonb_array_elements(coalesce(p_responsables,'[]'::jsonb)) loop v_alumno_id:=nullif(v_item->>'alumno_id','')::uuid; v_entrenador_id:=nullif(v_item->>'entrenador_id','')::uuid; if v_alumno_id is not null and v_entrenador_id is not null then if not exists(select 1 from public.grupo_alumnos where grupo_id=p_grupo_id and alumno_id=v_alumno_id) then raise exception 'El reparto de reportes contiene un alumno que no pertenece al grupo.'; end if; if v_entrenador_id<>v_principal and (p_entrenador_apoyo_id is null or v_entrenador_id<>p_entrenador_apoyo_id) then raise exception 'El responsable de reporte no es entrenador principal ni apoyo del grupo.'; end if; insert into public.grupo_reporte_responsable_app(grupo_id,alumno_id,entrenador_id) values(p_grupo_id,v_alumno_id,v_entrenador_id) on conflict(grupo_id,alumno_id) do update set entrenador_id=excluded.entrenador_id; end if; end loop; if exists(select 1 from public.grupo_alumnos ga where ga.grupo_id=p_grupo_id and not exists(select 1 from public.grupo_reporte_responsable_app rr where rr.grupo_id=p_grupo_id and rr.alumno_id=ga.alumno_id)) then raise exception 'El reparto de reportes está incompleto: faltan alumnos por asignar.'; end if; end;$function$;
-- 3. Las vistas conservan las columnas nuevas (entrenador_tercero_id /
--    entrenador_tercero): no molestan y quitarlas obliga a recrear las vistas
--    dependientes. Sin terceros, salen vacías.
